// ===== 客资改派弹窗（admin/owner/supervisor 可见）=====
// 状态：当前正在改派的 leadId / 原因 / 新销售 id
let reassignLeadState = { leadId: "", reason: "" };

function buildReassignLeadDialog() {
  // 取销售用户列表（state.users 中 role === 'sales'）
  const salesOptions = (state.users || [])
    .filter((u) => u && u.role === "sales")
    .map((u) => `<option value="${escapeHtmlAttribute(u.id || "")}">${escapeHtml(u.employeeName || u.username || u.id)}</option>`)
    .join("");
  return `
    <dialog id="reassignLeadDialog" class="reassign-dialog" style="padding:0;border:none;border-radius:12px;max-width:480px;width:90%;">
      <form method="dialog" style="padding:20px;">
        <h3 style="margin:0 0 8px;">改派销售</h3>
        <p class="muted" id="reassignLeadCaption" style="margin:0 0 12px;"></p>
        <label style="display:block;margin-bottom:10px;">
          <span style="display:block;font-weight:600;margin-bottom:4px;">新销售</span>
          <select id="reassignLeadSelect" style="width:100%;padding:6px 8px;">
            <option value="">请选择新销售</option>
            ${salesOptions}
          </select>
        </label>
        <label style="display:block;margin-bottom:10px;">
          <span style="display:block;font-weight:600;margin-bottom:4px;">改派原因（可选）</span>
          <textarea id="reassignLeadReason" rows="3" style="width:100%;padding:6px 8px;box-sizing:border-box;" placeholder="例如：原销售离职 / 客户行业不匹配"></textarea>
        </label>
        <div style="display:flex;justify-content:flex-end;gap:8px;margin-top:12px;">
          <button type="button" id="reassignLeadCancelBtn" class="ghost">取消</button>
          <button type="button" id="reassignLeadConfirmBtn" class="primary">确认改派</button>
        </div>
      </form>
    </dialog>
  `;
}

function ensureReassignDialogMounted() {
  if (document.getElementById("reassignLeadDialog")) return;
  const wrap = document.createElement("div");
  wrap.innerHTML = buildReassignLeadDialog();
  document.body.appendChild(wrap.firstElementChild);
}

function openReassignLeadDialog(leadId, leadLabel) {
  if (!leadId) return;
  ensureReassignDialogMounted();
  reassignLeadState = { leadId, reason: "" };
  const caption = document.getElementById("reassignLeadCaption");
  if (caption) caption.textContent = `客资：${leadLabel || leadId}`;
  const sel = document.getElementById("reassignLeadSelect");
  if (sel) sel.value = "";
  const reason = document.getElementById("reassignLeadReason");
  if (reason) reason.value = "";
  const dlg = document.getElementById("reassignLeadDialog");
  if (dlg && typeof dlg.showModal === "function") dlg.showModal();
  // 重新挂一次事件（弹窗是动态挂的）
  document.getElementById("reassignLeadConfirmBtn")?.addEventListener("click", submitReassignLead);
  document.getElementById("reassignLeadCancelBtn")?.addEventListener("click", closeReassignLeadDialog);
}

function closeReassignLeadDialog() {
  const dlg = document.getElementById("reassignLeadDialog");
  if (dlg && typeof dlg.close === "function") dlg.close();
}

async function submitReassignLead() {
  const leadId = reassignLeadState.leadId;
  const newAssigneeId = document.getElementById("reassignLeadSelect")?.value || "";
  const reason = document.getElementById("reassignLeadReason")?.value || "";
  if (!leadId) return closeReassignLeadDialog();
  if (!newAssigneeId) {
    setFlash("warn", "请选择新销售", "");
    return;
  }
  try {
    const res = await api(`/api/leads/${encodeURIComponent(leadId)}/reassign`, {
      method: "POST",
      body: JSON.stringify({ newAssigneeId, reason })
    });
    const newName = res?.lead?.assignedSalesUserName || "";
    setFlash("success", "已改派", newName ? `客资已指派给 ${newName}` : "客资已重新指派");
    // 同步本地缓存
    const lead = (state.leads || []).find((l) => l && l.id === leadId);
    if (lead && res?.lead) {
      lead.assignedSalesUserId = res.lead.assignedSalesUserId;
      lead.assignedSalesUserName = res.lead.assignedSalesUserName;
    }
    closeReassignLeadDialog();
    renderApp();
  } catch (e) {
    setFlash("warn", "改派失败", e?.message || "请稍后重试");
  }
}

